import{_ as e}from"./chunks/settings-robot.pc.en.95Z7NI6l.js";import{_ as o,o as a,c as s,a5 as r}from"./chunks/framework.BjM_ivYE.js";const m=JSON.parse('{"title":"3. Payload Setting","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"guides/add-on/payload-setting.md","filePath":"guides/add-on/payload-setting.md","lastUpdated":1790646309000}'),n={name:"guides/add-on/payload-setting.md"};function i(d,t,l,c,h,g){return a(),s("div",null,[...t[0]||(t[0]=[r('<h1 id="_3-payload-setting" tabindex="-1">3. Payload Setting <a class="header-anchor" href="#_3-payload-setting" aria-label="Permalink to &quot;3. Payload Setting&quot;">​</a></h1><p><strong>Goal:</strong> Register the <strong>mass</strong> and <strong>center of mass (X/Y/Z)</strong> of the add-on module in the RBQ app so the robot accounts for it while walking.</p><p><strong>Prerequisites:</strong> Step 2, <a href="/RBQ/guides/add-on/rail-spring-nut.html">Rail &amp; Spring Nut</a>, must be complete — the module has to be physically mounted on the rail.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><ul><li>Put the robot on <strong>flat, stable ground</strong>.</li><li>The RBQ app must be <strong>connected</strong> to the robot (<a href="/RBQ/guides/common/controller-wifi-connect.html">Controller &amp; Wi-Fi</a> complete).</li><li>Measure the module&#39;s center of mass as <strong>X / Y / Z (m)</strong> relative to the center of the robot body.</li></ul><h2 id="procedure" tabindex="-1">Procedure <a class="header-anchor" href="#procedure" aria-label="Permalink to &quot;Procedure&quot;">​</a></h2><ol><li>Open <strong>Robot settings › Payload setup</strong> in the app. The <code>Payload Configuration</code> screen appears.</li></ol><figure style="text-align:center;"><img src="'+e+'" alt="Robot parameters — Payload Configuration" style="display:block;margin:0 auto;max-width:100%;height:auto;"><figcaption style="text-align:center;">Robot settings › Payload setup</figcaption></figure><ol start="2"><li><p>In the <strong>slot table</strong> on the right, tap the slot you want and <strong>tick its checkbox.</strong> Ticking it fills in the catalogue defaults the robot holds.</p></li><li><p>Enter the values in the <strong>editor</strong> on the left:</p><ul><li><strong>Mass (kg)</strong> — mass of the add-on module</li><li><strong>X / Y / Z (m)</strong> — center of mass in the robot coordinate frame</li></ul><p>Tap a field to type, or use <code>−</code> and <code>+</code>; the <strong>Interval</strong> chips (<code>0.001</code>, <code>0.01</code>, <code>0.1</code>, <code>1</code>) set how much each press moves the value.</p></li><li><p>Check the <strong>total</strong> below the editor for the combined mass and center of mass. Going over the limit turns it red and blocks sending.</p></li><li><p>Press <strong>Set Payload</strong> and confirm with <strong>Apply</strong>. Unticked slots are sent with mass 0, which clears them.</p></li><li><p>After applying, press <strong>Get</strong> to re-read the stored values and confirm them.</p></li></ol><h2 id="buttons" tabindex="-1">Buttons <a class="header-anchor" href="#buttons" aria-label="Permalink to &quot;Buttons&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Button</th><th>Function</th></tr></thead><tbody><tr><td><strong>Checkbox</strong></td><td>Marks the slot as mounted (unticking sends mass 0, clearing it)</td></tr><tr><td><strong>Interval</strong></td><td>How much <code>−</code> and <code>+</code> move the value (<code>0.001</code>, <code>0.01</code>, <code>0.1</code>, <code>1</code>)</td></tr><tr><td><strong>Set Payload</strong></td><td>Applies every edited slot to the robot, via a confirmation</td></tr><tr><td><strong>Get</strong></td><td>Re-reads the values stored on the robot — edits in progress are discarded</td></tr></tbody></table><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE</p><p>Registering the payload is not enough on its own — the next step, ZMP calibration, adjusts the posture so the robot balances under the new load.</p></div></div><p>Allowed ranges and error messages are listed on <a href="/RBQ/manual/troubleshooting/payload_setting.html">Payload configuration</a>.</p><h2 id="next-step" tabindex="-1">Next step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next step&quot;">​</a></h2><p>With the payload registered, run the ZMP calibration to rebalance under the new weight:</p><p><strong><a href="/RBQ/guides/add-on/zmp-calibration.html">→ 4. ZMP Calibration</a></strong></p>',16)])])}const b=o(n,[["render",i]]);export{m as __pageData,b as default};
